<?php

declare(strict_types=1);

$base = __DIR__;

function w(string $path, array $t): void {
    $dir = dirname($path);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    $c = "<?php\n\ndeclare(strict_types=1);\n\nreturn [\n";
    foreach ($t as $k => $v) {
        $ev = str_replace("'", "\\'", $v);
        $c .= "    '{$k}' => '{$ev}',\n";
    }
    $c .= "];\n";
    file_put_contents($path, $c);
}

